{
  "criteria": [
    {
      "kind": "inclusion",
      "text": "Recurrent, persistent, and/or metastatic cervical cancer with squamous cell histology, for which there is not a curative-intent option (surgery or radiation therapy with or without chemotherapy).",
      "quote": "Recurrent, persistent, and/or metastatic cervical cancer with squamous cell histology, for which there is not a curative-intent option (surgery or radiation therapy with or without chemotherapy)."
    },
    {
      "kind": "inclusion",
      "text": "Tumor progression or recurrence after treatment with platinum therapy (must have been used to treat metastatic, persistent, or recurrent cervical cancer).",
      "quote": "Tumor progression or recurrence after treatment with platinum therapy (must have been used to treat metastatic, persistent, or recurrent cervical cancer)."
    },
    {
      "kind": "inclusion",
      "text": "Patient must have measurable disease as defined by RECIST 1.1. Measurable disease is defined as at least one lesion that can be accurately measured in at least 1 dimension (longest dimension to be recorded). Each lesion must be ≥10 mm when measured by computed tomography (CT), magnetic resonance imaging (MRI), or caliper measurement by clinical exam or must be ≥20 mm when measured by chest x-ray. Lymph nodes must be >15 mm in short axis when measured by CT or MRI.",
      "quote": "Patient must have measurable disease as defined by RECIST 1.1.",
      "thresholds": [
        {"test": "lesion size (CT/MRI/caliper)", "op": ">=", "value": 10, "unit": "mm"},
        {"test": "lesion size (chest x-ray)", "op": ">=", "value": 20, "unit": "mm"},
        {"test": "lymph node short axis", "op": ">", "value": 15, "unit": "mm"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Eastern Cooperative Oncology Group (ECOG) performance status ≤1",
      "quote": "Eastern Cooperative Oncology Group (ECOG) performance status ≤1",
      "thresholds": [
        {"test": "ECOG performance status", "op": "<=", "value": 1}
      ]
    },
    {
      "kind": "inclusion",
      "text": "≥18 years old",
      "quote": "≥18 years old",
      "thresholds": [
        {"test": "age", "op": ">=", "value": 18, "unit": "years"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Hepatic function: Total bilirubin ≤1.5x ULN (if liver metastases ≤3x ULN). Patients with Gilbert’s Disease and total bilirubin up to 3x ULN may be eligible after communication with and approval from the medical monitor.",
      "quote": "Total bilirubin ≤1.5x upper limit of normal (ULN; if liver metastases ≤3x ULN).",
      "thresholds": [
        {"test": "total bilirubin", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "total bilirubin (liver metastases)", "op": "<=", "value": 3, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Transaminases ≤3x ULN (or ≤5.0x ULN, if liver metastases)",
      "quote": "Transaminases ≤3x ULN (or ≤5.0x ULN, if liver metastases)",
      "thresholds": [
        {"test": "transaminases", "op": "<=", "value": 3, "unit": "x ULN"},
        {"test": "transaminases (liver metastases)", "op": "<=", "value": 5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Alkaline phosphatase ≤2.5x ULN (or ≤5.0x ULN, if liver or bone metastases)",
      "quote": "Alkaline phosphatase ≤2.5x ULN (or ≤5.0x ULN, if liver or bone metastases)",
      "thresholds": [
        {"test": "alkaline phosphatase", "op": "<=", "value": 2.5, "unit": "x ULN"},
        {"test": "alkaline phosphatase (liver or bone metastases)", "op": "<=", "value": 5, "unit": "x ULN"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Renal function: Serum creatinine ≤1.5x ULN or estimated creatinine clearance >45 mL/min",
      "quote": "Serum creatinine ≤1.5x ULN or estimated creatinine clearance >45 mL/min",
      "thresholds": [
        {"test": "serum creatinine", "op": "<=", "value": 1.5, "unit": "x ULN"},
        {"test": "creatinine clearance", "op": ">", "value": 45, "unit": "mL/min"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Bone marrow function: Hemoglobin ≥9.0 g/dL",
      "quote": "Hemoglobin ≥9.0 g/dL",
      "thresholds": [
        {"test": "hemoglobin", "op": ">=", "value": 9.0, "unit": "g/dL"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Absolute neutrophil count (ANC) ≥1.5x 10^9/L",
      "quote": "Absolute neutrophil count (ANC) ≥1.5x 10^9/L",
      "thresholds": [
        {"test": "ANC", "op": ">=", "value": 1.5, "unit": "10^9/L"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Platelet count ≥75 x 10^9/L",
      "quote": "Platelet count ≥75 x 10^9/L",
      "thresholds": [
        {"test": "platelet count", "op": ">=", "value": 75, "unit": "10^9/L"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Anticipated life expectancy >12 weeks",
      "quote": "Anticipated life expectancy >12 weeks",
      "thresholds": [
        {"test": "life expectancy", "op": ">", "value": 12, "unit": "weeks"}
      ]
    },
    {
      "kind": "inclusion",
      "text": "Willing and able to comply with clinic visits and study-related procedures",
      "quote": "Willing and able to comply with clinic visits and study-related procedures"
    },
    {
      "kind": "inclusion",
      "text": "Provide signed informed consent",
      "quote": "Provide signed informed consent"
    },
    {
      "kind": "inclusion",
      "text": "Able to understand and complete study-related questionnaires",
      "quote": "Able to understand and complete study-related questionnaires"
    },
    {
      "kind": "inclusion",
      "text": "Patients must meet at least one of the following criteria regarding prior bevacizumab therapy: a. Received prior bevacizumab-containing therapy, which was discontinued due to progression of disease; b. Received prior bevacizumab-containing therapy, which was discontinued due to toxicity; c. Was deemed unsuitable for prior bevacizumab therapy for one of the following reasons: (i) unacceptable risk of fistula formation, (ii) poorly controlled hypertension, (iii) “low risk” disease according to the Moore Criteria (Tewari 2015); d. Refused prior bevacizumab therapy; e. Did not have access to bevacizumab therapy due to logistical reasons (eg, lived in a region in which bevacizumab was not commercially available for patients with cervical cancer, or did not have insurance coverage for bevacizumab).",
      "quote": "Patients must meet at least one of the following criteria regarding prior bevacizumab therapy:"
    },
    {
      "kind": "inclusion",
      "text": "Patients must meet at least one of the following criteria regarding prior paclitaxel therapy: a. Received prior paclitaxel-containing therapy, which was discontinued due to progression of disease; b. Received prior paclitaxel-containing therapy, which was discontinued due to toxicity; c. Was deemed unsuitable for prior paclitaxel therapy for one of the following reasons: (i) neuropathy (ii) allergy to paclitaxel or its components; d. Refused prior paclitaxel therapy.",
      "quote": "Patients must meet at least one of the following criteria regarding prior paclitaxel therapy:"
    }
  ]
}
